// File: src/ProductDetail.js

import React from 'react';
import { useParams } from 'react-router-dom';

function ProductDetail() {
  // This grabs the ":id" portion from the URL (e.g., /product/fender-1).
  const { id } = useParams();

  // Normally, you'd look up your product data by ID from a list or API.
  // Here's a placeholder for demonstration:
  const mockProducts = [
    { id: 'epiphone-1', name: 'Epiphone Matt Heafy', model: '7 Strings', description: 'A heavy metal beast with 7 strings.' },
    { id: 'fender-1', name: 'Fender Stratocaster', model: 'Strat Classic', description: 'Iconic Strat tone, beloved by guitar legends.' }
    // Add more products if needed...
  ];

  // Find the product object from our list, or fallback to { ... } if not found
  const product = mockProducts.find((p) => p.id === id) || {
    id: 'unknown',
    name: 'Product Not Found',
    model: 'N/A',
    description: 'No product details available.'
  };

  // Example addToCart function
  const addToCart = () => {
    alert(`Added ${product.name} to cart!`);
    // For a real app:
    // 1. Use a cart context or local storage
    // 2. Or call a backend route to store items in the user's cart
  };

  // Inline styling for a minimal approach
  const detailContainerStyle = {
    padding: '2rem',
    color: '#fff'
  };

  const productTitleStyle = {
    fontSize: '2rem',
    marginBottom: '0.5rem'
  };

  const productSubtitleStyle = {
    fontStyle: 'italic',
    marginBottom: '1rem'
  };

  const descriptionStyle = {
    marginBottom: '2rem'
  };

  const buttonStyle = {
    background: 'rgba(255, 0, 0, 0.3)',
    padding: '0.5rem 1rem',
    border: 'none',
    borderRadius: '4px',
    color: '#fff',
    cursor: 'pointer',
    fontSize: '1rem',
    fontWeight: 'bold'
  };

  return (
    <div style={detailContainerStyle}>
      <h1 style={productTitleStyle}>Product Details</h1>
      <h2 style={productSubtitleStyle}>{product.name}</h2>
      <p style={descriptionStyle}>
        <strong>Model:</strong> {product.model}
        <br />
        <strong>Description:</strong> {product.description}
      </p>
      <button style={buttonStyle} onClick={addToCart}>
        Add to Cart
      </button>
    </div>
  );
}

export default ProductDetail;
